export const getListShareholderHistoryUrl = (id: string,
    params?: ListShareholderHistoryParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/shareholders/${id}/history?${stringifiedParams}` : `/api/shareholders/${id}/history`
}

